//! TLS material for the TrustTunnel endpoint.
//!
//! Every `main_hosts` entry in `hosts.toml` needs a PEM chain and key, and
//! the endpoint refuses to start without them. Two sources:
//!
//! * **Self-signed** (default). A P-256 leaf for the endpoint hostname,
//!   generated by [`crate::proxy::x509`]. Clients cannot verify it against a
//!   public root, so its DER rides inside every share link (deep-link tag
//!   `0x08`) and clients pin it. That pinning is why the validity is long
//!   ([`SELF_SIGNED_VALIDITY_DAYS`]): an expired pinned certificate breaks
//!   every link at once, and the only fix is re-sharing them all.
//! * **Operator-supplied** PEM chain + key — typically a Let's Encrypt
//!   certificate issued elsewhere. Validated here before it reaches the
//!   endpoint, because the endpoint load-tests certificates at startup and a
//!   bad one is a crash loop, not an error message.
//!
//! [`ca_trusted`] decides whether a chain needs embedding in links, the same
//! way `trusttunnel_endpoint -c` does (`lib/src/cert_verification.rs`): if it
//! verifies against public roots for the hostname, clients use their system
//! store and the link stays small; otherwise the chain is embedded.

use std::sync::Arc;

use anyhow::{anyhow, bail, Context, Result};
use base64ct::{Base64, Encoding as _};
use rustls::client::danger::ServerCertVerifier;
use rustls::client::WebPkiServerVerifier;
use rustls::RootCertStore;
use rustls_pki_types::pem::PemObject;
use rustls_pki_types::{CertificateDer, PrivateKeyDer, ServerName, UnixTime};

/// Ten years. See the module docs for why a pinned certificate wants years.
pub const SELF_SIGNED_VALIDITY_DAYS: i64 = 3650;

/// Characters per PEM body line (RFC 7468 §2).
const PEM_LINE: usize = 64;

/// A PEM chain + key pair, ready to write next to `hosts.toml`.
#[derive(Debug, Clone)]
pub struct Material {
    pub chain_pem: String,
    pub key_pem: String,
}

/// RFC 7468 textual encoding of one DER object.
pub fn pem_encode(label: &str, der: &[u8]) -> String {
    let b64 = Base64::encode_string(der);
    let mut out = format!("-----BEGIN {label}-----\n");
    for chunk in b64.as_bytes().chunks(PEM_LINE) {
        // base64 output is ASCII, so any byte boundary is a char boundary.
        out.push_str(std::str::from_utf8(chunk).unwrap_or_default());
        out.push('\n');
    }
    out.push_str(&format!("-----END {label}-----\n"));
    out
}

/// Generate a fresh self-signed certificate for `hostname`.
pub fn self_signed(hostname: &str) -> Result<Material> {
    let generated =
        crate::proxy::x509::generate_with_validity(hostname, SELF_SIGNED_VALIDITY_DAYS)
            .with_context(|| format!("generate a self-signed certificate for {hostname}"))?;
    Ok(Material {
        chain_pem: pem_encode("CERTIFICATE", &generated.cert_der),
        key_pem: pem_encode("PRIVATE KEY", &generated.key_pkcs8),
    })
}

/// Every `CERTIFICATE` block in `pem`, in order.
pub fn parse_chain(pem: &str) -> Result<Vec<CertificateDer<'static>>> {
    let chain = CertificateDer::pem_slice_iter(pem.as_bytes())
        .collect::<std::result::Result<Vec<_>, _>>()
        .map_err(|e| anyhow!("certificate chain is not valid PEM: {e:?}"))?;
    if chain.is_empty() {
        bail!("certificate chain contains no CERTIFICATE block");
    }
    Ok(chain)
}

/// The concatenated DER of the chain — deep-link tag `0x08`'s value.
pub fn chain_der(pem: &str) -> Result<Vec<u8>> {
    Ok(parse_chain(pem)?.iter().flat_map(|c| c.as_ref().to_vec()).collect())
}

fn parse_key(pem: &str) -> Result<PrivateKeyDer<'static>> {
    PrivateKeyDer::from_pem_slice(pem.as_bytes())
        .map_err(|e| anyhow!("private key is not a PEM PKCS#8 / SEC1 / PKCS#1 key: {e:?}"))
}

fn verify_with(
    roots: RootCertStore,
    chain: &[CertificateDer<'static>],
    hostname: &str,
) -> Result<()> {
    let provider = Arc::new(rustls::crypto::ring::default_provider());
    let verifier = WebPkiServerVerifier::builder_with_provider(Arc::new(roots), provider)
        .build()
        .context("build certificate verifier")?;
    let name = ServerName::try_from(hostname.to_string())
        .map_err(|_| anyhow!("'{hostname}' is not a valid TLS server name"))?;
    verifier
        .verify_server_cert(&chain[0], &chain[1..], &name, &[], UnixTime::now())
        .map(|_| ())
        .map_err(|e| anyhow!("{e}"))
}

/// Whether `chain_pem` verifies for `hostname` against the Mozilla root
/// store — i.e. whether clients can trust it without the chain embedded.
pub fn ca_trusted(chain_pem: &str, hostname: &str) -> bool {
    let Ok(chain) = parse_chain(chain_pem) else {
        return false;
    };
    let mut roots = RootCertStore::empty();
    roots.extend(webpki_roots::TLS_SERVER_ROOTS.iter().cloned());
    verify_with(roots, &chain, hostname).is_ok()
}

/// Check an operator-supplied chain + key before it reaches the endpoint:
/// both parse, the key is one the endpoint's TLS stack can sign with, the
/// key matches the leaf, and the chain is valid for `hostname` right now.
///
/// A chain that does not reach a public root is still accepted when it is
/// complete — anchored at its own last certificate (a self-signed leaf or a
/// private CA the operator included). Clients then receive it embedded in
/// the link and verify against exactly that.
pub fn validate(material: &Material, hostname: &str) -> Result<()> {
    let chain = parse_chain(&material.chain_pem)?;
    let key = parse_key(&material.key_pem)?;
    let signing = rustls::crypto::ring::sign::any_supported_type(&key)
        .map_err(|e| anyhow!("private key type is not supported: {e}"))?;
    rustls::sign::CertifiedKey::new(chain.clone(), signing)
        .keys_match()
        .map_err(|e| anyhow!("private key does not match the leaf certificate: {e}"))?;

    if ca_trusted(&material.chain_pem, hostname) {
        return Ok(());
    }
    let mut own = RootCertStore::empty();
    let anchor = chain.last().cloned().expect("parse_chain rejects an empty chain");
    own.add(anchor)
        .map_err(|e| anyhow!("last certificate in the chain cannot act as a trust anchor: {e}"))?;
    verify_with(own, &chain, hostname).with_context(|| {
        format!(
            "certificate chain does not verify for '{hostname}' (against public roots or \
             against its own last certificate)"
        )
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pem_round_trips_and_wraps_at_64_columns() {
        let der: Vec<u8> = (0..=255u8).cycle().take(1000).collect();
        let pem = pem_encode("CERTIFICATE", &der);
        assert!(pem.starts_with("-----BEGIN CERTIFICATE-----\n"));
        assert!(pem.ends_with("-----END CERTIFICATE-----\n"));
        assert!(pem.lines().all(|l| l.len() <= PEM_LINE || l.starts_with("-----")));
        let back = CertificateDer::pem_slice_iter(pem.as_bytes())
            .next()
            .unwrap()
            .unwrap();
        assert_eq!(back.as_ref(), der.as_slice());
    }

    #[test]
    fn self_signed_material_validates_for_its_hostname_only() {
        let m = self_signed("tt.example.net").unwrap();
        validate(&m, "tt.example.net").expect("own hostname");
        assert!(validate(&m, "other.example.net").is_err(), "wrong hostname");
        assert!(!ca_trusted(&m.chain_pem, "tt.example.net"), "not publicly trusted");
    }

    #[test]
    fn mismatched_key_is_rejected() {
        let a = self_signed("tt.example.net").unwrap();
        let b = self_signed("tt.example.net").unwrap();
        let mixed = Material { chain_pem: a.chain_pem, key_pem: b.key_pem };
        let err = validate(&mixed, "tt.example.net").unwrap_err().to_string();
        assert!(err.contains("does not match"), "{err}");
    }

    #[test]
    fn garbage_is_rejected_with_a_reason() {
        let m = Material { chain_pem: "nope".into(), key_pem: "nope".into() };
        assert!(validate(&m, "tt.example.net").is_err());
        assert!(chain_der("").is_err());
    }

    #[test]
    fn chain_der_concatenates_every_block() {
        let a = self_signed("a.example").unwrap();
        let b = self_signed("b.example").unwrap();
        let both = format!("{}{}", a.chain_pem, b.chain_pem);
        let der = chain_der(&both).unwrap();
        assert_eq!(
            der.len(),
            chain_der(&a.chain_pem).unwrap().len() + chain_der(&b.chain_pem).unwrap().len()
        );
    }
}
